annotations.vault.hashicorp.com/agent-inject-templat:
{{- with secret "secret/data/odoo" -}}
export POSTGRES_DB="{{ .Data.data.POSTGRES_DB }}"
export POSTGRES_USER="{{ .Data.data.POSTGRES_USER }}"
export POSTGRES_PASSWORD="{{ .Data.data.POSTGRES_PASSWORD }}"
{{- end }}

{{- with secret "secret/data/next_cloud" -}}
export POSTGRES_DB="{{ .Data.data.POSTGRES_DB }}"
export POSTGRES_USER="{{ .Data.data.POSTGRES_USER }}"
export POSTGRES_PASSWORD="{{ .Data.data.POSTGRES_PASSWORD }}"
{{- end }}

{{- with secret "secret/data/odoo" -}}
[options]
db_host = odoo-postgres
db_port = 5432
db_name = {{ .Data.data.POSTGRES_DB }}
db_user = {{ .Data.data.POSTGRES_USER }}
db_password = {{ .Data.data.POSTGRES_PASSWORD }}
addons_path = /usr/lib/python3/dist-packages/odoo/addons,/var/lib/odoo/addons/18.0,/mnt/extra-addons
data_dir = /var/lib/odoo
{{- end }}

{{- with secret "secret/data/mautic" -}}
export MYSQL_ROOT_PASSWORD="{{ .Data.data.MYSQL_ROOT_PASSWORD }}"
export MYSQL_DATABASE="{{ .Data.data.MYSQL_DB }}"
export MYSQL_USER="{{ .Data.data.MYSQL_USER }}"
export MYSQL_PASSWORD="{{ .Data.data.MYSQL_PASSWORD }}"
{{- end }}

{{- with secret "secret/data/frappe" -}}
export MYSQL_ROOT_PASSWORD="{{ .Data.data.FRAPPE_MYSQL_ROOT_PASSWORD }}"
export MYSQL_ROOT_HOST="%"
{{- end }}

{{- with secret "secret/data/frappe" -}}
export FRAPPE_MYSQL_ROOT_PASSWORD="{{ .Data.data.FRAPPE_MYSQL_ROOT_PASSWORD }}"
export FRAPPE_ENCRYPTION_KEY="{{ .Data.data.FRAPPE_ENCRYPTION_KEY }}"
{{- end }}

{{- with secret "secret/data/wordpress" -}}
export MARIADB_ROOT_PASSWORD="{{ .Data.data.WORDPRESS_DB_ROOT_PASSWORD }}"
export MARIADB_DATABASE="{{ .Data.data.WORDPRESS_DB_NAME }}"
export MARIADB_USER="{{ .Data.data.WORDPRESS_DB_USER }}"
export MARIADB_PASSWORD="{{ .Data.data.WORDPRESS_DB_PASSWORD }}"
{{- end }}

{{- with secret "secret/data/next_cloud" -}}
export POSTGRES_DB="{{ .Data.data.POSTGRES_DB }}"
export POSTGRES_USER="{{ .Data.data.POSTGRES_USER }}"
export POSTGRES_PASSWORD="{{ .Data.data.POSTGRES_PASSWORD }}"
{{- end }}

